package com.studywithlove.app;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;
public class WeeklyReportReceiver extends BroadcastReceiver{
 private static String tr(String l,String ru,String en,String az){return "en".equals(l)?en:("az".equals(l)?az:ru);}
 public static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences("study_progress",0);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,WeeklyReportReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,940,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(!p.getBoolean("weekly_report_enabled",true)){am.cancel(pi);pi.cancel();return;}Calendar x=Calendar.getInstance(AppTime.zone());x.set(Calendar.DAY_OF_WEEK,Calendar.SUNDAY);x.set(Calendar.HOUR_OF_DAY,19);x.set(Calendar.MINUTE,0);x.set(Calendar.SECOND,0);if(x.getTimeInMillis()<=System.currentTimeMillis())x.add(Calendar.WEEK_OF_YEAR,1);if(Build.VERSION.SDK_INT>=23){if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);}else am.setExact(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);}
 private static String formatLocal(Date d){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(AppTime.zone());return f.format(d);}
 @Override public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("study_progress",0);if(!p.getBoolean("weekly_report_enabled",true))return;String lang=p.getString("app_language","ru");int minutes=0,topics=0;Calendar cal=Calendar.getInstance(AppTime.zone());java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(AppTime.zone());int bestMinutes=0;String bestDay="—";java.text.SimpleDateFormat dayName=new java.text.SimpleDateFormat("EEEE","en".equals(lang)?Locale.ENGLISH:("az".equals(lang)?new Locale("az"):new Locale("ru")) );dayName.setTimeZone(AppTime.zone());for(int d=0;d<7;d++){Calendar q=(Calendar)cal.clone();q.add(Calendar.DAY_OF_YEAR,-d);int dayMinutes=p.getInt("focus_minutes_"+f.format(q.getTime()),0);minutes+=dayMinutes;if(dayMinutes>bestMinutes){bestMinutes=dayMinutes;bestDay=dayName.format(q.getTime());}}Set<String> history=p.getStringSet("study_days",new TreeSet<String>());Set<String> days=new TreeSet<>();for(String day:history){try{java.text.SimpleDateFormat parseDate=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);parseDate.setTimeZone(AppTime.zone());Date d=parseDate.parse(day);if(System.currentTimeMillis()>=d.getTime()&&(System.currentTimeMillis()-d.getTime())<7L*86400000L)days.add(day);}catch(Exception ignored){}}for(Map.Entry<String,?> e:p.getAll().entrySet())if(e.getKey().startsWith("topic_completed_at_")){long ts=(e.getValue() instanceof Long)?(Long)e.getValue():0;if(ts>0&&System.currentTimeMillis()-ts<7L*86400000L)topics++;}if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){schedule(c);return;}NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("weekly_report",tr(lang,"Недельный отчёт","Weekly report","Həftəlik hesabat"),NotificationManager.IMPORTANCE_DEFAULT));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"weekly_report"):new Notification.Builder(c);Intent open=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,941,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.setSmallIcon(R.drawable.ic_notification).setContentTitle(tr(lang,"Твоя неделя в Study with Love 🌸","Your week in Study with Love 🌸","Study with Love-da həftən 🌸")).setContentText(tr(lang,"Фокус: ","Focus: ","Fokus: ")+minutes+tr(lang," мин · "," min · "," dəq · ")+days.size()+tr(lang," учебных дней · лучший день: "," study days · best day: "," dərs günü · ən yaxşı gün: ")+bestDay).setStyle(new Notification.BigTextStyle().bigText(tr(lang,"За неделю: ","This week: ","Bu həftə: ")+minutes+tr(lang," минут по таймеру, "," minutes of focus, "," dəqiqə fokus, ")+days.size()+tr(lang," учебных дней и "," study days and "," dərs günü və ")+topics+tr(lang," завершённых тем. Самый продуктивный день: "," completed topics. Most productive day: "," tamamlanmış mövzu. Ən məhsuldar gün: ")+bestDay+" ("+bestMinutes+tr(lang," мин). Ты молодец — каждый шаг важен!"," min). Great job — every step matters!"," dəq). Əla iş — hər addım vacibdir!"))).setContentIntent(pi).setAutoCancel(true);nm.notify(942,b.build());schedule(c);}
}
